import sys
from collections import deque

class T:
    __slots__ = ('v', 'l', 'r')
    def __init__(self, v=0, l=None, r=None):
        self.v = v; self.l = l; self.r = r


def build(arr):
    if not arr or arr[0] == 'n':
        return None
    root = T(int(arr[0]))
    q = deque([root])
    i = 1
    while q and i < len(arr):
        node = q.popleft()
        if i < len(arr) and arr[i] != 'n':
            node.l = T(int(arr[i])); q.append(node.l)
        i += 1
        if i < len(arr) and arr[i] != 'n':
            node.r = T(int(arr[i])); q.append(node.r)
        i += 1
    return root


def sum_brute(root):
    nums = []
    def dfs(node, path):
        if not node:
            return
        cur = path + str(node.v)
        if not node.l and not node.r:
            nums.append(int(cur))
            return
        dfs(node.l, cur)
        dfs(node.r, cur)
    dfs(root, '')
    return sum(nums)


if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    root = build(data[1:1 + n])
    print(sum_brute(root))

